```go
package main

import (
	"fmt"
	"math"
)

const SIZE = 1000002

var (
	s      [SIZE]byte
	p      []int
	minVal int
)

func sieve() {
	for i := 2; i < SIZE; i++ {
		if s[i] == 0 {
			p = append(p, i)
			for j := 2; i*j < SIZE; j++ {
				s[i*j] = 1
			}
		}
	}
}

func max(x, y int) int {
	if x > y {
		return x
	}
	return y
}

func solve(x, l int) {
	if x < minVal {
		minVal = x
	}

	if l == 0 {
		return
	}

	ox := x
	lf := -1

	for i := 0; i < len(p) && p[i]*p[i] <= x; i++ {
		if ox%p[i] == 0 {
			lf = max(lf, p[i])
			for ox%p[i] == 0 {
				ox /= p[i]
			}
		}
	}
	if ox > 1 && ox != x {
		lf = max(lf, ox)
	}

	if lf == -1 {
		return
	}

	if l == 1 {
		x = x - lf + 1
		if x < minVal {
			minVal = x
		}
		return
	}

	start := x - lf + 1
	end := lf * (x / lf)
	for d := start; d < end; d++ {
		solve(d, l-1)
	}
}

func main() {
	s[0] = 1
	s[1] = 1
	sieve()
	minVal = math.MaxInt32

	var x2 int
	fmt.Scan(&x2)
	solve(x2, 2)
	fmt.Print(minVal)
}
```

